// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Transfer ownership to a benign address so that actor is not the owner
        address newOwner = makeAddr("newOwner");
        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // Now actor (non-owner) calls NETM
        vm.prank(actor);
        try c.NETM() { } catch { }

        // The invariant: after any call to NETM, the owner's balance must be totalDistributed (250M tokens)
        // and no other address (especially the caller if they are not the owner) should have received a balance from this.
        // More generally, the sum of all balances must not exceed totalDistributed and the owner must hold totalDistributed.
        // A simple, universal check: owner's balance must equal totalDistributed (the initial distribution amount).
        // Bug: In the mutant, balances[msg.sender] = totalDistributed, so a non-owner caller gets the tokens,
        // and the owner gets nothing, violating the equality.
        assertTrue(c.balanceOf(newOwner) == c.totalDistributed());
    }
}

