// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // NETM can only be called by the current owner, who is initially the deployer.
        // We let the fuzzer pick any address to become the owner, then call NETM.
        vm.prank(address(this));
        c.transferOwnership(actor);
        vm.prank(actor);
        c.NETM();
        // After NETM, the balance of the (new) owner must match totalDistributed.
        uint256 ownerBal = c.balanceOf(actor);
        uint256 totDist = c.totalDistributed();
        assertEq(ownerBal, totDist, "owner balance must equal totalDistributed");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.NETM() {
            // NETM succeeded, meaning caller is the owner (onlyOwner modifier)
            // After a successful NETM, the balance of the address returned by the public owner getter must equal totalDistributed
            address newOwner = c.owner();
            uint256 ownerBalance = c.balanceOf(newOwner);
            assertEq(ownerBalance, c.totalDistributed());
        } catch {
            // If NETM reverted (non-owner), the property is vacuously true for the correct contract
            assertTrue(true);
        }
    }
}
